import React, { useState } from 'react';
import { Search, MapPin, Phone, MessageSquare, Filter, Award, ShieldAlert } from 'lucide-react';
import { Link } from 'react-router-dom';

export default function SearchPage() {
  const [selectedBloodGroup, setSelectedBloodGroup] = useState('সব');
  const [selectedDistrict, setSelectedDistrict] = useState('সব');

  // ডামি ডোনার লিস্ট (কাছাকাছি দূরত্ব অনুযায়ী সাজানো)
  const [donors] = useState([
    {
      id: 1,
      name: "তানভীর আহমেদ",
      avatar: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150",
      bloodGroup: "O+",
      district: "ঢাকা",
      area: "মিরপুর-১০",
      distance: "১.২ কিমি দূরে",
      lastDonated: "৪ মাস আগে",
      isAvailable: true,
      phone: "01711000000"
    },
    {
      id: 2,
      name: "মেহেদী হাসান",
      avatar: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150",
      bloodGroup: "A+",
      district: "ঢাকা",
      area: "ধানমন্ডি-৩২",
      distance: "৩.৫ কিমি দূরে",
      lastDonated: "৬ মাস আগে",
      isAvailable: true,
      phone: "01811000000"
    },
    {
      id: 3,
      name: "নুসরাত জাহান",
      avatar: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150",
      bloodGroup: "B+",
      district: "চট্টগ্রাম",
      area: "জিইসি মোড়",
      distance: "১২ কিমি দূরে",
      lastDonated: "৫ মাস আগে",
      isAvailable: false,
      phone: "01911000000"
    }
  ]);

  const bloodGroups = ['সব', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];
  const districts = ['সব', 'ঢাকা', 'চট্টগ্রাম', 'রাজশাহী', 'সিলেট', 'খুলনা', 'বরিশাল', 'রংপুর', 'ময়মনসিংহ'];

  // ফিল্টারিং লজিক
  const filteredDonors = donors.filter(donor => {
    const matchesGroup = selectedBloodGroup === 'সব' || donor.bloodGroup === selectedBloodGroup;
    const matchesDistrict = selectedDistrict === 'সব' || donor.district === selectedDistrict;
    return matchesGroup && matchesDistrict;
  });

  return (
    <div className="max-w-2xl mx-auto px-4 py-6 space-y-6">
      
      {/* Search Header */}
      <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 space-y-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-2xl bg-rose-50 text-brand-600 flex items-center justify-center font-bold">
            <Search className="w-5 h-5" />
          </div>
          <div>
            <h1 className="text-base font-black text-slate-900">স্মার্ট ব্লাড সার্চ</h1>
            <p className="text-xs text-slate-500 font-medium">নিকটস্থ রক্তদাতা খুঁজে বের করুন</p>
          </div>
        </div>

        {/* Filters */}
        <div className="space-y-3 pt-2">
          {/* Blood Group Selector */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-2">রক্তের গ্রুপ বেছে নিন</label>
            <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none">
              {bloodGroups.map((bg) => (
                <button
                  key={bg}
                  onClick={() => setSelectedBloodGroup(bg)}
                  className={`px-3.5 py-1.5 rounded-xl text-xs font-bold border shrink-0 transition ${
                    selectedBloodGroup === bg
                      ? 'bg-brand-600 text-white border-brand-600 shadow-sm'
                      : 'bg-slate-50 text-slate-600 border-slate-200 hover:border-slate-300'
                  }`}
                >
                  {bg}
                </button>
              ))}
            </div>
          </div>

          {/* District Selector */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">জেলা নির্বাচন করুন</label>
            <div className="relative">
              <Filter className="w-4 h-4 absolute left-3.5 top-3 text-slate-400" />
              <select
                value={selectedDistrict}
                onChange={(e) => setSelectedDistrict(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 text-xs font-bold bg-slate-50 focus:outline-none focus:border-brand-600"
              >
                {districts.map((d) => (
                  <option key={d} value={d}>{d}</option>
                ))}
              </select>
            </div>
          </div>
        </div>
      </div>

      {/* Donors List */}
      <div className="space-y-3">
        <p className="text-xs font-bold text-slate-500 px-1">
          {filteredDonors.length} জন রক্তদাতা পাওয়া গেছে
        </p>

        {filteredDonors.map((donor) => (
          <div key={donor.id} className="bg-white rounded-3xl p-5 border border-slate-100 shadow-sm space-y-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <img src={donor.avatar} alt={donor.name} className="w-12 h-12 rounded-full object-cover border-2 border-rose-100" />
                <div>
                  <h3 className="text-sm font-bold text-slate-900 flex items-center gap-1.5">
                    {donor.name}
                    {donor.isAvailable ? (
                      <span className="bg-emerald-100 text-emerald-700 text-[10px] px-2 py-0.5 rounded-full font-bold">রক্ত দিতে প্রস্তুত</span>
                    ) : (
                      <span className="bg-slate-100 text-slate-500 text-[10px] px-2 py-0.5 rounded-full font-bold">অনুপলব্ধ</span>
                    )}
                  </h3>
                  <div className="flex items-center gap-1 text-[11px] text-slate-500 font-medium mt-0.5">
                    <MapPin className="w-3 h-3 text-brand-600" />
                    <span>{donor.area}, {donor.district}</span>
                    <span className="text-brand-600 font-bold ml-1">({donor.distance})</span>
                  </div>
                </div>
              </div>

              {/* Group Badge */}
              <div className="w-11 h-11 rounded-2xl bg-brand-600 text-white font-black text-sm flex items-center justify-center shadow-md shadow-brand-600/20">
                {donor.bloodGroup}
              </div>
            </div>

            <div className="text-xs text-slate-500 font-medium bg-slate-50 p-2.5 rounded-xl flex items-center justify-between">
              <span>সর্বশেষ রক্তদান: <strong className="text-slate-800">{donor.lastDonated}</strong></span>
              <span className="flex items-center gap-1 text-slate-400">
                <Award className="w-3.5 h-3.5 text-amber-500" /> ভেরিফাইড ডোনার
              </span>
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 pt-1">
              <a
                href={`tel:${donor.phone}`}
                className="flex-1 bg-rose-50 hover:bg-rose-100 text-brand-700 font-bold text-xs py-2.5 rounded-xl flex items-center justify-center gap-1.5 transition"
              >
                <Phone className="w-3.5 h-3.5" /> কল করুন
              </a>
              <Link
                to="/messages"
                className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs py-2.5 rounded-xl flex items-center justify-center gap-1.5 transition"
              >
                <MessageSquare className="w-3.5 h-3.5 text-slate-600" /> মেসেজ দিন
              </Link>
            </div>
          </div>
        ))}
      </div>

    </div>
  );
}
